1	// Harmless CLI stand-in for the installed SDK's output-schema lifecycle. No provider is run.
2	import { readFileSync, writeFileSync, writeSync } from 'node:fs';
3	import { basename, dirname } from 'node:path';
4	import process from 'node:process';
5	import { setInterval } from 'node:timers';
6	
7	if (basename(process.argv[1] ?? '') === 'exec' && process.argv.includes('--experimental-json')) {
8	  const args = process.argv.slice(2);
9	  const schemaPath = args[args.indexOf('--output-schema') + 1];
10	  const schemaText = readFileSync(schemaPath, 'utf8');
11	  writeFileSync(
12	    process.env.GG_SCHEMA_RECORD,
13	    JSON.stringify({
14	      pid: process.pid,
15	      schemaPath,
16	      schemaDirectory: dirname(schemaPath),
17	      schemaText,
18	      schema: JSON.parse(schemaText),
19	      argv: args,
20	    }),
21	  );
22	  readFileSync(0);
23	  const event = (value) => writeSync(1, JSON.stringify(value) + '\n');
24	  event({ type: 'thread.started', thread_id: 'schema-fixture' });
25	  event({ type: 'turn.started' });
26	  if (process.env.GG_SCHEMA_MODE === 'error') {
27	    writeSync(2, 'Controlled schema fixture failure\n');
28	    process.exit(7);
29	  }
30	  if (process.env.GG_SCHEMA_MODE === 'abort') {
31	    await new Promise(() => {
32	      setInterval(() => undefined, 1000);
33	    });
34	  }
